import { EventEmitter } from 'events';

interface CloudConfig {
  region: string;
  endpoint: string;
  maxRetries: number;
  enableCallbackChaining: boolean;
}

interface ResourceState {
  id: string;
  status: 'pending' | 'provisioning' | 'active' | 'deleting' | 'deleted';
  refCount: number;
  metadata: Record<string, string>;
}

type LifecycleHook = (resource: ResourceState, manager: ResourceManager) => Promise<void>;

class ConfigLoader {
  private static instance: ConfigLoader;
  private config: CloudConfig;

  private constructor() {
    this.config = {
      region: process.env.CLOUD_REGION || 'us-east-1',
      endpoint: process.env.CLOUD_ENDPOINT || 'https://api.cloud.internal',
      maxRetries: parseInt(process.env.MAX_RETRIES || '3', 10),
      enableCallbackChaining: process.env.ENABLE_CALLBACK_CHAINING !== 'false'
    };
  }

  static getInstance(): ConfigLoader {
    if (!ConfigLoader.instance) {
      ConfigLoader.instance = new ConfigLoader();
    }
    return ConfigLoader.instance;
  }

  getConfig(): CloudConfig {
    return { ...this.config };
  }
}

class ResourceManager extends EventEmitter {
  private resources: Map<string, ResourceState> = new Map();
  private lifecycleHooks: Map<string, LifecycleHook[]> = new Map();
  private operationLock: Set<string> = new Set();
  private config: CloudConfig;

  constructor() {
    super();
    this.config = ConfigLoader.getInstance().getConfig();
  }

  registerHook(event: string, hook: LifecycleHook): void {
    const hooks = this.lifecycleHooks.get(event) || [];
    hooks.push(hook);
    this.lifecycleHooks.set(event, hooks);
  }

  private async executeHooks(event: string, resource: ResourceState): Promise<void> {
    const hooks = this.lifecycleHooks.get(event) || [];
    if (this.config.enableCallbackChaining) {
      for (const hook of hooks) {
        await hook(resource, this);
      }
    }
  }

  async provisionResource(id: string, metadata: Record<string, string> = {}): Promise<ResourceState> {
    if (this.resources.has(id)) {
      const existing = this.resources.get(id)!;
      existing.refCount++;
      return existing;
    }

    const resource: ResourceState = {
      id,
      status: 'pending',
      refCount: 1,
      metadata
    };

    this.resources.set(id, resource);
    resource.status = 'provisioning';
    await this.executeHooks('provisioning', resource);
    resource.status = 'active';
    this.emit('resource:active', resource);
    return resource;
  }

  async releaseResource(id: string): Promise<boolean> {
    const resource = this.resources.get(id);
    if (!resource) return false;

    resource.refCount--;

    if (resource.refCount <= 0) {
      resource.status = 'deleting';
      await this.executeHooks('deleting', resource);

      // After hooks execute, check if resource still exists and is in deleting state
      const current = this.resources.get(id);
      if (current && current.status === 'deleting') {
        current.status = 'deleted';
        this.resources.delete(id);
        this.emit('resource:deleted', { id });
        return true;
      }
    }
    return false;
  }

  getResource(id: string): ResourceState | undefined {
    return this.resources.get(id);
  }

  getActiveResourceCount(): number {
    return this.resources.size;
  }
}

class InfrastructureOrchestrator {
  private manager: ResourceManager;
  private dependencyGraph: Map<string, Set<string>> = new Map();

  constructor() {
    this.manager = new ResourceManager();
    this.setupDefaultHooks();
  }

  private setupDefaultHooks(): void {
    this.manager.registerHook('deleting', async (resource, mgr) => {
      const dependents = this.dependencyGraph.get(resource.id);
      if (dependents) {
        for (const depId of dependents) {
          await mgr.releaseResource(depId);
        }
        this.dependencyGraph.delete(resource.id);
      }
    });

    this.manager.registerHook('provisioning', async (resource, mgr) => {
      if (resource.metadata['requires']) {
        const deps = resource.metadata['requires'].split(',');
        for (const dep of deps) {
          const trimmed = dep.trim();
          if (trimmed) {
            await mgr.provisionResource(trimmed, { parent: resource.id });
            const depSet = this.dependencyGraph.get(resource.id) || new Set();
            depSet.add(trimmed);
            this.dependencyGraph.set(resource.id, depSet);
          }
        }
      }
    });
  }

  async deploy(resourceId: string, metadata: Record<string, string> = {}): Promise<ResourceState> {
    return this.manager.provisionResource(resourceId, metadata);
  }

  async teardown(resourceId: string): Promise<boolean> {
    return this.manager.releaseResource(resourceId);
  }

  getManager(): ResourceManager {
    return this.manager;
  }
}

export { ConfigLoader, ResourceManager, InfrastructureOrchestrator, ResourceState };
